// Live-data overlay written by scripts/refresh-data.mjs (BLS, CDC, and — with
// API keys — FBI/Census). Merged over the base rows below at load time.
// One merge rule, shared by the app and the refresh script: base row, then the
// transcribed static facts, then the live overlay. The refresh must merge onto
// the RAW rows -- merging onto already-merged data let a field the new overlay
// dropped survive from the previous one.
//
// There are no derived trends any more. Crime and income history used to be one
// national shape stretched to end on each location's latest value -- every
// state got the same "-9.9%" -- and it was read as real. History now comes only
// from the source's own yearly table (violentCrimeSeries, incomeSeries).
export const mergeRows = (rows, overlay = {}) => rows.map(r => ({ ...r, ...(facts[r.id] || {}), ...(overlay[r.id] || {}) }));

// Vintage of each metric that is NOT refreshed live. The refresh overrides an
// entry only when that source actually succeeds (e.g. a keyed FBI pull), so
// every label on screen names the year of the number beside it.
export const BASE_VINTAGES = Object.freeze({
    violentCrime: 'FBI 2024',
    propertyCrime: 'FBI 2024',
    income: 'ACS 2023',
    poverty: 'ACS',
    urbanPct: '2020 Census',
    education: 'ACS 2021'
});
export const VINTAGES = { ...BASE_VINTAGES, ...(baked.meta?.vintages || {}) };

// ---- States (50 + DC) ---------------------------------------------------
